-- Fill parsable schemas for existing seed rows without overwriting customized definitions.
update game set config_schemas = '[{"path":"server.properties","format":"properties","category":"Server","generate_before_start":true,"managed_fields":{"server-ip":"game_server.ip","server-port":"game_server.port","query.port":"game_server.query_port"},"schema":{"type":"object","x-groups":["Identity","Access","Networking","World"],"properties":{"motd":{"type":"string","title":"MOTD","default":"A Minecraft Server","x-group":"Identity","x-order":0},"max-players":{"type":"integer","title":"Max players","default":32,"minimum":1,"maximum":500,"x-group":"Access","x-order":0},"online-mode":{"type":"boolean","title":"Online mode","default":true,"x-group":"Access","x-order":1},"white-list":{"type":"boolean","title":"Whitelist","default":false,"x-group":"Access","x-order":2},"server-ip":{"type":"string","title":"Bind IP","default":"0.0.0.0","x-group":"Networking","x-order":0,"x-managed":{"source":"game_server.ip"}},"server-port":{"type":"integer","title":"Server port","default":25565,"minimum":1,"maximum":65535,"x-group":"Networking","x-order":1,"x-managed":{"source":"game_server.port"}},"enable-query":{"type":"boolean","title":"Enable query","default":true,"x-group":"Networking","x-order":2},"query.port":{"type":"integer","title":"Query port","default":25565,"minimum":1,"maximum":65535,"x-group":"Networking","x-order":3,"x-managed":{"source":"game_server.query_port"}},"level-name":{"type":"string","title":"World name","default":"world","x-group":"World","x-order":0},"level-seed":{"type":"string","title":"World seed","default":"","x-group":"World","x-order":1},"gamemode":{"type":"string","title":"Game mode","default":"survival","enum":["survival","creative","adventure","spectator"],"x-group":"World","x-order":2}}}}]' where id = 'minecraft' and config_schemas is null;
update game set config_schemas = '[{"path":"settings.xml","format":"xml","category":"Server","xml_key_mode":{"mode":"attributes","element":"property","key_attr":"name","value_attr":"value"},"managed_fields":{"ServerPort":"game_server.port"},"schema":{"type":"object","x-groups":["Identity","Access","Networking"],"properties":{"ServerName":{"type":"string","title":"Server name","default":"My 7 Days to Die Server","x-group":"Identity","x-order":0},"ServerDescription":{"type":"string","title":"Description","default":"","x-group":"Identity","x-order":1},"ServerPassword":{"type":"string","title":"Password","default":"","x-group":"Access","x-order":0},"ServerMaxPlayerCount":{"type":"integer","title":"Max players","default":32,"minimum":1,"maximum":64,"x-group":"Access","x-order":1},"ServerPort":{"type":"integer","title":"Server port","default":26900,"minimum":1,"maximum":65535,"x-group":"Networking","x-order":0,"x-managed":{"source":"game_server.port"}}}}}]' where id = '7_days_to_die' and config_schemas is null;

-- Upgrade existing default Minecraft heap arguments to server-managed memory placeholders.
update game
set linux_start_args_template = replace(
    replace(
        linux_start_args_template,
        '"ownership":"editable","tokens":["-Xms512M"],"label":"Min heap size"',
        '"ownership":"system","tokens":["-Xms{{MAX_MEMORY_MB}}M"],"label":"Min heap size","managed_source":"game_server.max_memory_mb"'
    ),
    '"ownership":"editable","tokens":["-Xmx2G"],"label":"Max heap size"',
    '"ownership":"system","tokens":["-Xmx{{MAX_MEMORY_MB}}M"],"label":"Max heap size","managed_source":"game_server.max_memory_mb"'
)
where id = 'minecraft'
  and (
      linux_start_args_template like '%"tokens":["-Xms512M"]%'
      or linux_start_args_template like '%"tokens":["-Xmx2G"]%'
  );

update game
set windows_start_args_template = replace(
    replace(
        windows_start_args_template,
        '"ownership":"editable","tokens":["-Xms512M"],"label":"Min heap size"',
        '"ownership":"system","tokens":["-Xms{{MAX_MEMORY_MB}}M"],"label":"Min heap size","managed_source":"game_server.max_memory_mb"'
    ),
    '"ownership":"editable","tokens":["-Xmx2G"],"label":"Max heap size"',
    '"ownership":"system","tokens":["-Xmx{{MAX_MEMORY_MB}}M"],"label":"Max heap size","managed_source":"game_server.max_memory_mb"'
)
where id = 'minecraft'
  and (
      windows_start_args_template like '%"tokens":["-Xms512M"]%'
      or windows_start_args_template like '%"tokens":["-Xmx2G"]%'
  );

